-- ============================================================================
-- Little Horizons ERP - Esquema de Base de Datos
-- Sistema de Gestion Educativa
-- Version: 3.0 (basada en el script del anexo v2.0, con cambios justificados)
-- Motor: MySQL 8.0.16 o superior (REQUERIDO: antes de 8.0.16 los CHECK se
--        aceptan pero NO se aplican)
-- ============================================================================
--
-- REGISTRO DE CAMBIOS RESPECTO AL SCRIPT DEL ANEXO (con justificacion)
--
--  1. 'año_academico' -> 'anio_academico': la letra 'ñ' en identificadores
--     genera problemas de codificacion con JDBC, consolas y herramientas.
--  2. Se agrego 'RC' (Registro Civil) a estudiantes.tipo_documento: los
--     ninos de preescolar y primaria usan RC, no TI.
--  3. Estados de estudiantes y matriculas alineados con el enunciado
--     (Activo, Graduado, Retirado).
--  4. Nueva tabla 'horarios_clase': el enunciado (1.2) exige registrar dias y
--     horas de cada materia por profesor para evitar conflictos basicos.
--  5. Nueva tabla 'cargos_estudiante': permite valores personalizados
--     (descuentos, becas) segun 3.1 y detectar morosos segun 3.2, ya que
--     'pagos' solo guarda lo ya pagado.
--  6. 'pagos.id_acudiente' ahora es NOT NULL (la factura exige un cliente) y
--     se agrego 'pagos.id_cargo' (opcional) para ligar el pago a un cargo.
--  7. 'facturas' ahora guarda subtotal, IVA, total, cliente, contenido del QR
--     simulado y resolucion; se agrego 'detalle_factura' (lista de conceptos).
--     'nombre_archivo_pdf' -> 'nombre_archivo' (por indicacion del instructor
--     la factura se genera como .txt).
--  8. Nueva tabla 'configuracion_institucion': datos del colegio (razon
--     social, NIT, resolucion simulada) sin quemarlos en el codigo.
--  9. posicion_obtenida pasa de VARCHAR libre a ENUM.
-- 10. membresias_club: restriccion UNIQUE (estudiante, club) para evitar
--     duplicados.
-- 11. ON DELETE CASCADE reemplazado por RESTRICT en tablas con valor
--     historico (notas, asistencia, pagos, facturas, prestamos, matriculas):
--     borrar un estudiante no debe borrar su historial financiero/academico.
--     El retiro se maneja con el campo 'estado'.
-- 12. CHECK adicionales (montos, cupos, horas, fechas, horarios).
-- 13. Se eliminaron indices redundantes que duplicaban los de UNIQUE.
-- 14. El nombre de la base de datos es 'erp_little_horizons' (el comentario
--     del anexo mencionaba 'little_horizons_erp', lo cual era inconsistente).
-- ============================================================================

-- ============================================================================
-- SECCION 1 - DDL (Data Definition Language)
-- ============================================================================

DROP DATABASE IF EXISTS erp_little_horizons;
CREATE DATABASE erp_little_horizons CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE erp_little_horizons;

SET NAMES utf8mb4;

-- ============================================
-- 0. CONFIGURACION DE LA INSTITUCION
-- ============================================

CREATE TABLE configuracion_institucion (
    id_configuracion TINYINT PRIMARY KEY DEFAULT 1,
    razon_social VARCHAR(150) NOT NULL,
    nit VARCHAR(20) NOT NULL,
    direccion VARCHAR(255) NOT NULL,
    telefono VARCHAR(20) NOT NULL,
    correo_electronico VARCHAR(100) NOT NULL,
    prefijo_factura VARCHAR(10) NOT NULL DEFAULT 'LH',
    resolucion_numero VARCHAR(30) NOT NULL COMMENT 'Resolucion DIAN de habilitacion (simulada)',
    resolucion_fecha DATE NOT NULL,
    rango_desde INT NOT NULL,
    rango_hasta INT NOT NULL,
    porcentaje_iva DECIMAL(4,2) NOT NULL DEFAULT 0.00 COMMENT 'IVA aplicado a las facturas (servicios educativos suelen estar excluidos)',
    CHECK (id_configuracion = 1),
    CHECK (rango_hasta > rango_desde),
    CHECK (porcentaje_iva >= 0 AND porcentaje_iva <= 100)
) ENGINE=InnoDB COMMENT='Datos del colegio y de la resolucion de facturacion (una sola fila)';

-- ============================================
-- 1. MODULO DE ESTUDIANTES Y ACUDIENTES
-- ============================================

CREATE TABLE grados (
    id_grado INT AUTO_INCREMENT PRIMARY KEY,
    nombre_grado VARCHAR(50) NOT NULL UNIQUE COMMENT 'Ej: Preescolar, Primero, Segundo, ... Once',
    nivel_numerico INT NOT NULL UNIQUE COMMENT 'Nivel numerico para ordenamiento (0 para preescolar, 1-11 para grados)',
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    CHECK (nivel_numerico >= 0 AND nivel_numerico <= 11)
) ENGINE=InnoDB COMMENT='Catalogo de grados academicos del colegio';

CREATE TABLE estudiantes (
    id_estudiante INT AUTO_INCREMENT PRIMARY KEY,
    tipo_documento ENUM('RC', 'TI', 'CC', 'CE', 'Pasaporte') NOT NULL DEFAULT 'TI',
    numero_documento VARCHAR(20) NOT NULL UNIQUE,
    primer_nombre VARCHAR(100) NOT NULL,
    segundo_nombre VARCHAR(100),
    primer_apellido VARCHAR(100) NOT NULL,
    segundo_apellido VARCHAR(100),
    fecha_nacimiento DATE NOT NULL,
    genero ENUM('M', 'F', 'Otro') NOT NULL,
    direccion VARCHAR(255),
    telefono VARCHAR(20),
    correo_electronico VARCHAR(100),
    tipo_sangre VARCHAR(5),
    alergias TEXT,
    condiciones_medicas TEXT,
    fecha_ingreso DATE NOT NULL,
    estado ENUM('Activo', 'Graduado', 'Retirado') NOT NULL DEFAULT 'Activo',
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_estado (estado),
    INDEX idx_nombre (primer_apellido, segundo_apellido, primer_nombre)
) ENGINE=InnoDB COMMENT='Informacion completa de estudiantes';

CREATE TABLE acudientes (
    id_acudiente INT AUTO_INCREMENT PRIMARY KEY,
    tipo_documento ENUM('CC', 'CE', 'Pasaporte') NOT NULL DEFAULT 'CC',
    numero_documento VARCHAR(20) NOT NULL UNIQUE,
    primer_nombre VARCHAR(100) NOT NULL,
    segundo_nombre VARCHAR(100),
    primer_apellido VARCHAR(100) NOT NULL,
    segundo_apellido VARCHAR(100),
    parentesco VARCHAR(50) NOT NULL COMMENT 'Padre, Madre, Abuelo, Tio, Tutor Legal, etc.',
    telefono_principal VARCHAR(20) NOT NULL,
    telefono_secundario VARCHAR(20),
    correo_electronico VARCHAR(100),
    direccion VARCHAR(255),
    ocupacion VARCHAR(100),
    es_responsable_financiero BOOLEAN DEFAULT TRUE COMMENT 'Indica si es responsable de pagos',
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_nombre (primer_apellido, segundo_apellido)
) ENGINE=InnoDB COMMENT='Acudientes y tutores legales';

-- Relacion muchos a muchos. Regla en la aplicacion: todo estudiante debe tener
-- al menos un acudiente (se crean ambos en una misma transaccion).
CREATE TABLE estudiante_acudiente (
    id_estudiante INT NOT NULL,
    id_acudiente INT NOT NULL,
    es_principal BOOLEAN DEFAULT FALSE COMMENT 'Acudiente principal para comunicaciones',
    es_contacto_emergencia BOOLEAN DEFAULT TRUE COMMENT 'Disponible para emergencias',
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (id_estudiante, id_acudiente),
    FOREIGN KEY (id_estudiante) REFERENCES estudiantes(id_estudiante) ON DELETE CASCADE,
    FOREIGN KEY (id_acudiente) REFERENCES acudientes(id_acudiente) ON DELETE CASCADE,
    INDEX idx_acudiente (id_acudiente)
) ENGINE=InnoDB COMMENT='Relacion entre estudiantes y sus acudientes';

CREATE TABLE matriculas (
    id_matricula INT AUTO_INCREMENT PRIMARY KEY,
    id_estudiante INT NOT NULL,
    id_grado INT NOT NULL,
    anio_academico INT NOT NULL COMMENT 'Anio academico (ej: 2026)',
    estado_matricula ENUM('Activo', 'Graduado', 'Retirado') NOT NULL DEFAULT 'Activo',
    fecha_matricula DATE NOT NULL,
    fecha_retiro DATE,
    observaciones TEXT,
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_estudiante) REFERENCES estudiantes(id_estudiante) ON DELETE RESTRICT,
    FOREIGN KEY (id_grado) REFERENCES grados(id_grado) ON DELETE RESTRICT,
    UNIQUE KEY matricula_unica (id_estudiante, anio_academico),
    INDEX idx_anio_grado (anio_academico, id_grado),
    INDEX idx_estado (estado_matricula),
    CHECK (anio_academico >= 2000 AND anio_academico <= 2100),
    CHECK (fecha_retiro IS NULL OR fecha_retiro >= fecha_matricula)
) ENGINE=InnoDB COMMENT='Historial de matriculas de estudiantes por anio y grado';

-- ============================================
-- 2. MODULO ACADEMICO
-- ============================================

CREATE TABLE materias (
    id_materia INT AUTO_INCREMENT PRIMARY KEY,
    codigo_materia VARCHAR(20) NOT NULL UNIQUE COMMENT 'Codigo unico de la materia (ej: MAT-5, ESP-3)',
    nombre_materia VARCHAR(100) NOT NULL,
    descripcion TEXT,
    id_grado INT NOT NULL COMMENT 'Grado al que pertenece la materia',
    horas_semanales INT NOT NULL DEFAULT 2 COMMENT 'Horas semanales asignadas',
    esta_activa BOOLEAN DEFAULT TRUE,
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_grado) REFERENCES grados(id_grado) ON DELETE RESTRICT,
    INDEX idx_grado (id_grado),
    INDEX idx_activa (esta_activa),
    CHECK (horas_semanales > 0 AND horas_semanales <= 40)
) ENGINE=InnoDB COMMENT='Catalogo de materias por grado';

CREATE TABLE profesores (
    id_profesor INT AUTO_INCREMENT PRIMARY KEY,
    tipo_documento ENUM('CC', 'CE', 'Pasaporte') NOT NULL DEFAULT 'CC',
    numero_documento VARCHAR(20) NOT NULL UNIQUE,
    primer_nombre VARCHAR(100) NOT NULL,
    segundo_nombre VARCHAR(100),
    primer_apellido VARCHAR(100) NOT NULL,
    segundo_apellido VARCHAR(100),
    correo_electronico VARCHAR(100) NOT NULL UNIQUE,
    telefono VARCHAR(20),
    especializacion VARCHAR(100) COMMENT 'Area de especializacion (Matematicas, Espanol, etc.)',
    fecha_contratacion DATE NOT NULL,
    estado ENUM('Activo', 'Inactivo', 'Licencia') NOT NULL DEFAULT 'Activo',
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_estado (estado),
    INDEX idx_nombre (primer_apellido, segundo_apellido)
) ENGINE=InnoDB COMMENT='Informacion de profesores';

CREATE TABLE asignaciones_profesor (
    id_asignacion INT AUTO_INCREMENT PRIMARY KEY,
    id_profesor INT NOT NULL,
    id_materia INT NOT NULL,
    anio_academico INT NOT NULL,
    seccion VARCHAR(10) NOT NULL DEFAULT 'A' COMMENT 'Seccion o grupo (A, B, C)',
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_profesor) REFERENCES profesores(id_profesor) ON DELETE RESTRICT,
    FOREIGN KEY (id_materia) REFERENCES materias(id_materia) ON DELETE RESTRICT,
    UNIQUE KEY asignacion_unica (id_profesor, id_materia, anio_academico, seccion),
    INDEX idx_materia_anio (id_materia, anio_academico),
    CHECK (anio_academico >= 2000 AND anio_academico <= 2100)
) ENGINE=InnoDB COMMENT='Asignacion de profesores a materias por anio academico';

-- NUEVA: horarios de clase (enunciado 1.2)
CREATE TABLE horarios_clase (
    id_horario INT AUTO_INCREMENT PRIMARY KEY,
    id_asignacion INT NOT NULL,
    dia_semana ENUM('Lunes', 'Martes', 'Miercoles', 'Jueves', 'Viernes') NOT NULL,
    hora_inicio TIME NOT NULL,
    hora_fin TIME NOT NULL,
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_asignacion) REFERENCES asignaciones_profesor(id_asignacion) ON DELETE CASCADE,
    UNIQUE KEY horario_unico (id_asignacion, dia_semana, hora_inicio),
    INDEX idx_dia_hora (dia_semana, hora_inicio),
    CHECK (hora_fin > hora_inicio)
) ENGINE=InnoDB COMMENT='Dias y horas en que cada profesor dicta cada materia (deteccion de conflictos en la aplicacion)';

CREATE TABLE inscripciones_materia (
    id_inscripcion INT AUTO_INCREMENT PRIMARY KEY,
    id_estudiante INT NOT NULL,
    id_materia INT NOT NULL,
    anio_academico INT NOT NULL,
    periodo_academico ENUM('I', 'II', 'III', 'IV') NOT NULL COMMENT 'Periodo academico',
    seccion VARCHAR(10) COMMENT 'Seccion o grupo asignado',
    fecha_inscripcion DATE NOT NULL,
    estado ENUM('Activa', 'Retirada', 'Completada') NOT NULL DEFAULT 'Activa',
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_estudiante) REFERENCES estudiantes(id_estudiante) ON DELETE RESTRICT,
    FOREIGN KEY (id_materia) REFERENCES materias(id_materia) ON DELETE RESTRICT,
    UNIQUE KEY inscripcion_unica (id_estudiante, id_materia, anio_academico, periodo_academico),
    INDEX idx_materia_periodo (id_materia, periodo_academico),
    CHECK (anio_academico >= 2000 AND anio_academico <= 2100)
) ENGINE=InnoDB COMMENT='Inscripcion de estudiantes en materias especificas';

CREATE TABLE registros_academicos (
    id_registro INT AUTO_INCREMENT PRIMARY KEY,
    id_estudiante INT NOT NULL,
    id_materia INT NOT NULL,
    id_profesor INT NOT NULL,
    anio_academico INT NOT NULL,
    periodo_academico ENUM('I', 'II', 'III', 'IV', 'Final') NOT NULL,
    valor_nota DECIMAL(2,1) NOT NULL COMMENT 'Nota de 0.0 a 5.0 segun estandar colombiano',
    observaciones TEXT,
    fecha_registro DATE NOT NULL,
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (id_estudiante) REFERENCES estudiantes(id_estudiante) ON DELETE RESTRICT,
    FOREIGN KEY (id_materia) REFERENCES materias(id_materia) ON DELETE RESTRICT,
    FOREIGN KEY (id_profesor) REFERENCES profesores(id_profesor) ON DELETE RESTRICT,
    CHECK (valor_nota >= 0.0 AND valor_nota <= 5.0),
    CHECK (anio_academico >= 2000 AND anio_academico <= 2100),
    UNIQUE KEY registro_unico (id_estudiante, id_materia, anio_academico, periodo_academico),
    INDEX idx_materia_periodo (id_materia, periodo_academico),
    INDEX idx_profesor (id_profesor)
) ENGINE=InnoDB COMMENT='Registro de calificaciones de estudiantes';

CREATE TABLE asistencias (
    id_asistencia INT AUTO_INCREMENT PRIMARY KEY,
    id_estudiante INT NOT NULL,
    id_materia INT NOT NULL,
    fecha_asistencia DATE NOT NULL,
    estado_asistencia ENUM('Presente', 'Ausente', 'Tardanza', 'Excusa Médica') NOT NULL,
    observaciones TEXT,
    registrado_por INT COMMENT 'ID del profesor que registro la asistencia',
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_estudiante) REFERENCES estudiantes(id_estudiante) ON DELETE RESTRICT,
    FOREIGN KEY (id_materia) REFERENCES materias(id_materia) ON DELETE RESTRICT,
    FOREIGN KEY (registrado_por) REFERENCES profesores(id_profesor) ON DELETE RESTRICT,
    UNIQUE KEY asistencia_unica (id_estudiante, id_materia, fecha_asistencia),
    INDEX idx_materia_fecha (id_materia, fecha_asistencia),
    INDEX idx_estado_fecha (estado_asistencia, fecha_asistencia)
) ENGINE=InnoDB COMMENT='Registro de asistencia diaria de estudiantes';

-- ============================================
-- 3. MODULO DE ACTIVIDADES EXTRACURRICULARES
-- ============================================

CREATE TABLE clubes (
    id_club INT AUTO_INCREMENT PRIMARY KEY,
    nombre_club VARCHAR(100) NOT NULL UNIQUE,
    descripcion TEXT,
    id_profesor_supervisor INT COMMENT 'Profesor encargado del club',
    capacidad_maxima INT NOT NULL DEFAULT 30 COMMENT 'Cupo maximo de estudiantes',
    horario_reunion VARCHAR(100) COMMENT 'Dias y horario de reunion (ej: Martes 3-5 PM)',
    esta_activo BOOLEAN DEFAULT TRUE,
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (id_profesor_supervisor) REFERENCES profesores(id_profesor) ON DELETE RESTRICT,
    INDEX idx_activo (esta_activo),
    CHECK (capacidad_maxima > 0)
) ENGINE=InnoDB COMMENT='Catalogo de clubes extracurriculares';

CREATE TABLE membresias_club (
    id_membresia INT AUTO_INCREMENT PRIMARY KEY,
    id_estudiante INT NOT NULL,
    id_club INT NOT NULL,
    fecha_ingreso DATE NOT NULL,
    estado_membresia ENUM('Activo', 'Retirado') NOT NULL DEFAULT 'Activo',
    fecha_retiro DATE,
    motivo_retiro TEXT,
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_estudiante) REFERENCES estudiantes(id_estudiante) ON DELETE RESTRICT,
    FOREIGN KEY (id_club) REFERENCES clubes(id_club) ON DELETE RESTRICT,
    UNIQUE KEY membresia_unica (id_estudiante, id_club),
    INDEX idx_club_estado (id_club, estado_membresia),
    CHECK (fecha_retiro IS NULL OR fecha_retiro >= fecha_ingreso)
) ENGINE=InnoDB COMMENT='Membresias de estudiantes en clubes (el cupo se valida contando membresias Activo)';

CREATE TABLE eventos (
    id_evento INT AUTO_INCREMENT PRIMARY KEY,
    nombre_evento VARCHAR(150) NOT NULL,
    descripcion TEXT,
    tipo_evento ENUM('Académico', 'Cultural', 'Deportivo', 'Social', 'Científico') NOT NULL,
    fecha_evento DATE NOT NULL,
    lugar VARCHAR(150),
    tiene_competencia BOOLEAN NOT NULL DEFAULT FALSE COMMENT 'Indica si el evento tiene competencia con posiciones',
    id_organizador INT COMMENT 'Profesor organizador del evento',
    esta_activo BOOLEAN DEFAULT TRUE,
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_organizador) REFERENCES profesores(id_profesor) ON DELETE RESTRICT,
    INDEX idx_fecha (fecha_evento),
    INDEX idx_tipo (tipo_evento),
    INDEX idx_activo (esta_activo)
) ENGINE=InnoDB COMMENT='Catalogo de eventos del colegio';

CREATE TABLE participantes_evento (
    id_participacion INT AUTO_INCREMENT PRIMARY KEY,
    id_evento INT NOT NULL,
    id_estudiante INT NOT NULL,
    rol_participacion ENUM('Participante', 'Competidor', 'Organizador', 'Asistente') NOT NULL DEFAULT 'Participante',
    posicion_obtenida ENUM('1er Lugar', '2do Lugar', '3er Lugar', 'Participante') COMMENT 'Solo aplica si el evento tiene competencia',
    observaciones TEXT,
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_evento) REFERENCES eventos(id_evento) ON DELETE RESTRICT,
    FOREIGN KEY (id_estudiante) REFERENCES estudiantes(id_estudiante) ON DELETE RESTRICT,
    UNIQUE KEY participacion_unica (id_evento, id_estudiante),
    INDEX idx_estudiante (id_estudiante)
) ENGINE=InnoDB COMMENT='Registro de participacion de estudiantes en eventos';

-- ============================================
-- 4. MODULO FINANCIERO
-- ============================================

CREATE TABLE conceptos_pago (
    id_concepto INT AUTO_INCREMENT PRIMARY KEY,
    codigo_concepto VARCHAR(20) NOT NULL UNIQUE,
    nombre_concepto VARCHAR(100) NOT NULL,
    descripcion TEXT,
    monto_base DECIMAL(10,2) NOT NULL COMMENT 'Valor base del concepto en pesos colombianos',
    es_recurrente BOOLEAN DEFAULT FALSE COMMENT 'Indica si es un pago recurrente (ej: pension mensual)',
    esta_activo BOOLEAN DEFAULT TRUE,
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    INDEX idx_activo (esta_activo),
    CHECK (monto_base > 0)
) ENGINE=InnoDB COMMENT='Catalogo de conceptos de pago del colegio';

-- NUEVA: cargos por estudiante (valores personalizados y control de morosos)
CREATE TABLE cargos_estudiante (
    id_cargo INT AUTO_INCREMENT PRIMARY KEY,
    id_estudiante INT NOT NULL,
    id_concepto INT NOT NULL,
    anio_academico INT NOT NULL,
    periodo_academico ENUM('I', 'II', 'III', 'IV', 'Anual') NOT NULL,
    valor_base DECIMAL(10,2) NOT NULL COMMENT 'Copia del monto base del concepto al momento de generar el cargo',
    descuento DECIMAL(10,2) NOT NULL DEFAULT 0.00 COMMENT 'Descuento por hermanos, beca parcial, etc.',
    valor_final DECIMAL(10,2) AS (valor_base - descuento) STORED,
    motivo_descuento VARCHAR(150),
    fecha_vencimiento DATE NOT NULL,
    estado_cargo ENUM('Pendiente', 'Pagado', 'Anulado') NOT NULL DEFAULT 'Pendiente',
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (id_estudiante) REFERENCES estudiantes(id_estudiante) ON DELETE RESTRICT,
    FOREIGN KEY (id_concepto) REFERENCES conceptos_pago(id_concepto) ON DELETE RESTRICT,
    INDEX idx_estudiante_estado (id_estudiante, estado_cargo),
    INDEX idx_vencimiento_estado (fecha_vencimiento, estado_cargo),
    CHECK (valor_base > 0),
    CHECK (descuento >= 0 AND descuento < valor_base),
    CHECK (anio_academico >= 2000 AND anio_academico <= 2100)
) ENGINE=InnoDB COMMENT='Valores a cobrar por estudiante; los Pendiente vencidos hace mas de un mes son morosos';

CREATE TABLE pagos (
    id_pago INT AUTO_INCREMENT PRIMARY KEY,
    id_estudiante INT NOT NULL,
    id_acudiente INT NOT NULL COMMENT 'Acudiente que realizo el pago (cliente de la factura)',
    id_concepto INT NOT NULL,
    id_cargo INT COMMENT 'Cargo que se esta pagando (opcional para pagos sin cargo previo)',
    monto_pagado DECIMAL(10,2) NOT NULL,
    fecha_pago DATE NOT NULL,
    metodo_pago ENUM('Efectivo', 'Transferencia', 'Tarjeta Débito', 'Tarjeta Crédito', 'Cheque') NOT NULL,
    numero_recibo VARCHAR(50) NOT NULL UNIQUE,
    anio_academico INT COMMENT 'Anio al que aplica el pago',
    periodo_academico ENUM('I', 'II', 'III', 'IV', 'Anual') COMMENT 'Periodo al que aplica el pago',
    notas TEXT,
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_estudiante) REFERENCES estudiantes(id_estudiante) ON DELETE RESTRICT,
    FOREIGN KEY (id_acudiente) REFERENCES acudientes(id_acudiente) ON DELETE RESTRICT,
    FOREIGN KEY (id_concepto) REFERENCES conceptos_pago(id_concepto) ON DELETE RESTRICT,
    FOREIGN KEY (id_cargo) REFERENCES cargos_estudiante(id_cargo) ON DELETE RESTRICT,
    INDEX idx_estudiante_fecha (id_estudiante, fecha_pago),
    INDEX idx_acudiente (id_acudiente),
    INDEX idx_concepto (id_concepto),
    INDEX idx_fecha (fecha_pago),
    CHECK (monto_pagado > 0)
) ENGINE=InnoDB COMMENT='Registro de todos los pagos realizados';

CREATE TABLE facturas (
    id_factura INT AUTO_INCREMENT PRIMARY KEY,
    numero_factura VARCHAR(50) NOT NULL UNIQUE COMMENT 'Numero consecutivo de factura (prefijo + consecutivo)',
    id_acudiente INT NOT NULL COMMENT 'Cliente: acudiente responsable del pago',
    fecha_emision DATE NOT NULL,
    subtotal DECIMAL(12,2) NOT NULL,
    iva DECIMAL(12,2) NOT NULL DEFAULT 0.00,
    total DECIMAL(12,2) NOT NULL,
    cufe VARCHAR(128) NOT NULL UNIQUE COMMENT 'Codigo Unico de Factura Electronica (simulado, hash)',
    contenido_qr VARCHAR(500) COMMENT 'Cadena que contendria el codigo QR (simulado)',
    resolucion_numero VARCHAR(30) NOT NULL COMMENT 'Resolucion DIAN usada (simulada)',
    nombre_archivo VARCHAR(255) COMMENT 'Nombre del archivo generado (.txt)',
    ruta_archivo VARCHAR(500) COMMENT 'Ruta donde se guardo el archivo',
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_acudiente) REFERENCES acudientes(id_acudiente) ON DELETE RESTRICT,
    INDEX idx_fecha_emision (fecha_emision),
    INDEX idx_acudiente (id_acudiente),
    CHECK (subtotal >= 0 AND iva >= 0),
    CHECK (total = subtotal + iva)
) ENGINE=InnoDB COMMENT='Encabezado de facturas electronicas generadas';

CREATE TABLE detalle_factura (
    id_detalle INT AUTO_INCREMENT PRIMARY KEY,
    id_factura INT NOT NULL,
    id_pago INT NOT NULL COMMENT 'Pago facturado en esta linea (un pago solo se factura una vez)',
    descripcion VARCHAR(255) NOT NULL,
    cantidad INT NOT NULL DEFAULT 1,
    valor_unitario DECIMAL(10,2) NOT NULL,
    subtotal DECIMAL(12,2) NOT NULL,
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (id_factura) REFERENCES facturas(id_factura) ON DELETE RESTRICT,
    FOREIGN KEY (id_pago) REFERENCES pagos(id_pago) ON DELETE RESTRICT,
    UNIQUE KEY pago_facturado_una_vez (id_pago),
    INDEX idx_factura (id_factura),
    CHECK (cantidad > 0),
    CHECK (valor_unitario > 0),
    CHECK (subtotal = cantidad * valor_unitario)
) ENGINE=InnoDB COMMENT='Lineas (conceptos) de cada factura';

-- ============================================
-- 5. MODULO DE GESTION DE RECURSOS
-- ============================================

CREATE TABLE categorias_recurso (
    id_categoria INT AUTO_INCREMENT PRIMARY KEY,
    nombre_categoria VARCHAR(50) NOT NULL UNIQUE,
    descripcion TEXT,
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB COMMENT='Categorias de recursos (Libro, Equipo de Laboratorio, etc.)';

CREATE TABLE recursos (
    id_recurso INT AUTO_INCREMENT PRIMARY KEY,
    codigo_recurso VARCHAR(50) NOT NULL UNIQUE COMMENT 'Codigo de inventario unico',
    nombre_recurso VARCHAR(150) NOT NULL,
    id_categoria INT NOT NULL,
    descripcion TEXT,
    fecha_adquisicion DATE,
    ubicacion_fisica VARCHAR(100) COMMENT 'Ubicacion fisica (Biblioteca, Laboratorio 1, etc.)',
    estado_recurso ENUM('Disponible', 'Prestado', 'En Mantenimiento', 'Dado de Baja') NOT NULL DEFAULT 'Disponible',
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (id_categoria) REFERENCES categorias_recurso(id_categoria) ON DELETE RESTRICT,
    INDEX idx_estado (estado_recurso),
    INDEX idx_categoria (id_categoria),
    INDEX idx_nombre (nombre_recurso)
) ENGINE=InnoDB COMMENT='Inventario de recursos prestables del colegio';

CREATE TABLE prestamos_estudiante (
    id_prestamo INT AUTO_INCREMENT PRIMARY KEY,
    id_recurso INT NOT NULL,
    id_estudiante INT NOT NULL COMMENT 'Estudiante que toma prestado el recurso',
    fecha_prestamo DATE NOT NULL,
    fecha_devolucion_esperada DATE NOT NULL,
    fecha_devolucion_real DATE,
    estado_prestamo ENUM('Activo', 'Devuelto', 'Vencido') NOT NULL DEFAULT 'Activo',
    observaciones TEXT,
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (id_recurso) REFERENCES recursos(id_recurso) ON DELETE RESTRICT,
    FOREIGN KEY (id_estudiante) REFERENCES estudiantes(id_estudiante) ON DELETE RESTRICT,
    INDEX idx_recurso_estado (id_recurso, estado_prestamo),
    INDEX idx_estudiante (id_estudiante),
    INDEX idx_estado_devolucion (estado_prestamo, fecha_devolucion_esperada),
    CHECK (fecha_devolucion_esperada >= fecha_prestamo),
    CHECK (fecha_devolucion_real IS NULL OR fecha_devolucion_real >= fecha_prestamo)
) ENGINE=InnoDB COMMENT='Registro de prestamos de recursos a estudiantes';

CREATE TABLE prestamos_profesor (
    id_prestamo INT AUTO_INCREMENT PRIMARY KEY,
    id_recurso INT NOT NULL,
    id_profesor INT NOT NULL COMMENT 'Profesor que toma prestado el recurso',
    fecha_prestamo DATE NOT NULL,
    fecha_devolucion_esperada DATE NOT NULL,
    fecha_devolucion_real DATE,
    estado_prestamo ENUM('Activo', 'Devuelto', 'Vencido') NOT NULL DEFAULT 'Activo',
    observaciones TEXT,
    fecha_creacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (id_recurso) REFERENCES recursos(id_recurso) ON DELETE RESTRICT,
    FOREIGN KEY (id_profesor) REFERENCES profesores(id_profesor) ON DELETE RESTRICT,
    INDEX idx_recurso_estado (id_recurso, estado_prestamo),
    INDEX idx_profesor (id_profesor),
    INDEX idx_estado_devolucion (estado_prestamo, fecha_devolucion_esperada),
    CHECK (fecha_devolucion_esperada >= fecha_prestamo),
    CHECK (fecha_devolucion_real IS NULL OR fecha_devolucion_real >= fecha_prestamo)
) ENGINE=InnoDB COMMENT='Registro de prestamos de recursos a profesores';

